const thunderArcherSheet=new Image();thunderArcherSheet.assetSrc='assets/thunder-archer-v1.png';let thunderArrows=[];
function beginThunderArcher(e){e.state='attack';e.elapsed=0;e.struck=false;e.facing=p.x-e.x-(p.y-e.y)<0?-1:1;e.attack={pattern:'thunderRingArrow',bespoke:true,windup:1,origin:{x:e.x,y:e.y},target:{x:p.x,y:p.y},fired:false};}
function stepThunderArrow(arrow,dt){arrow.age=Math.round((arrow.age+dt)*1e6)/1e6;if(!arrow.hit&&arrow.age>=.35){if(!lineClear(arrow.origin,arrow.target))return false;arrow.hit=true;if(dist(p,arrow.target)<=50+1e-8&&lineClear(arrow.target,p))hurt(56);playSound('impact',arrow.target.x,arrow.target.y);}if(!arrow.ring&&arrow.age>=1.15){arrow.ring=true;let d=dist(p,arrow.target);if(d>50+1e-8&&d<=180+1e-8&&lineClear(arrow.target,p))hurt(52);playSound('impact',arrow.target.x,arrow.target.y);}return arrow.age<1.35;}
function advanceThunderArrows(dt,skipFresh=false){if(!started||paused||dead||!Number.isFinite(dt)||dt<=0)return;thunderArrows=thunderArrows.filter(a=>a.owner===p&&(skipFresh&&a.spawnClock===clock||stepThunderArrow(a,dt)));}
const thunderArcherAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r6e3')return thunderArcherAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='thunderRingArrow'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=440&&clear){beginThunderArcher(e);return;}e.state='idle';if(d>800&&!e.aware||d<=300&&clear)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,90*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,16)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.4;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;if(!a.fired&&e.elapsed>=1){a.fired=true;e.struck=true;if(lineClear(a.origin,a.target)){let arrow={owner:p,origin:{...a.origin},target:{...a.target},age:0,hit:false,ring:false,spawnClock:clock};if(stepThunderArrow(arrow,e.elapsed-1))thunderArrows.push(arrow);}playSound('arrow',e.x,e.y);}if(e.elapsed>=1.6){e.attack=null;e.state='idle';e.t=2.6;}
};
const thunderArcherUpdateBase=update;update=dt=>{let active=started&&!paused&&!dead;thunderArcherUpdateBase(dt);if(active)advanceThunderArrows(dt,true);};
const thunderArcherLoadBase=loadWorld;loadWorld=(...args)=>{thunderArrows=[];return thunderArcherLoadBase(...args);};
const thunderArcherDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r6e3'||!thunderArcherSheet.complete||!thunderArcherSheet.naturalWidth||!thunderArcherSheet.naturalHeight)return thunderArcherDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='thunderRingArrow')f={row:2,col:e.elapsed<.4?0:e.elapsed<1?1:e.elapsed<1.2?2:3};let q=project(e.x,e.y),sw=thunderArcherSheet.naturalWidth/4,sh=thunderArcherSheet.naturalHeight/3,w=230,h=w*sh/sw,anchor=.92;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,thunderArcherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(thunderArcherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const thunderArcherSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r6e3'?140:thunderArcherSizeBase(e);
function drawThunderArrowRing(target,fired){let q=project(target.x,target.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle=fired?'#fff1b477':'#d5b86724';ctx.strokeStyle=fired?'#fff6d8':'#d9bf79';ctx.lineWidth=fired?3:1;ctx.beginPath();ctx.arc(0,0,180,0,Math.PI*2);ctx.arc(0,0,50,Math.PI*2,0,true);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();groundRing(target.x,target.y,50,'#bceacc',2);}
const thunderArcherGroundBase=drawGroundEffects;drawGroundEffects=()=>{thunderArcherGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r6e3'):enemies)){let a=e.attack;if(e.species==='r6e3'&&e.hp>0&&a?.pattern==='thunderRingArrow'&&!a.fired&&visibleAt(a.target.x,a.target.y))groundRing(a.target.x,a.target.y,50,'#e8bd85',2);}for(let a of thunderArrows){if(a.owner!==p||!visibleAt(a.target.x,a.target.y))continue;if(a.hit)drawThunderArrowRing(a.target,a.ring);else groundRing(a.target.x,a.target.y,50,'#fff0b2',2);}};
const thunderArcherEffectsBase=drawEffects;drawEffects=()=>{thunderArcherEffectsBase();ctx.save();ctx.strokeStyle='#ffe5a3';ctx.lineWidth=3;for(let a of thunderArrows){if(a.owner!==p||a.age>=.35||!visibleAt(a.target.x,a.target.y))continue;let t=a.age/.35,q=project(a.origin.x+(a.target.x-a.origin.x)*t,a.origin.y+(a.target.y-a.origin.y)*t);q.y-=Math.sin(t*Math.PI)*70+20*(1-t);ctx.beginPath();ctx.moveTo(q.x-8,q.y-16);ctx.lineTo(q.x,q.y);ctx.stroke();}ctx.restore();};
